operation.expression:
(: $records is your input sequence :)
let $records := $input.partyIds

(: How many records do we have? :)
let $n := count($records)

(: Base size and remainder for fair split across 4 parts :)
let $base := floor($n div 4)
let $rem  := $n mod 4

(: Part sizes: distribute remainder to first, then second, then third :)
let $firstCount  := $base + (if ($rem >= 1) then 1 else 0)
let $secondCount := $base + (if ($rem >= 2) then 1 else 0)
let $thirdCount  := $base + (if ($rem >= 3) then 1 else 0)
let $fourthCount := $n - $firstCount - $secondCount - $thirdCount

(: Slice the sequence accordingly :)
let $t_firstRecords  := subsequence($records, 1, $firstCount)
let $t_secondRecords := subsequence($records, $firstCount + 1, $secondCount)
let $t_thirdRecords  := subsequence($records, $firstCount + $secondCount + 1, $thirdCount)
let $t_fourthRecords := subsequence($records, $firstCount + $secondCount + $thirdCount + 1, $fourthCount)

return
<service-results>
  <first>
    { for $x in $t_firstRecords  return <record>{$x}</record> }
  </first>
  <second>
    { for $x in $t_secondRecords return <record>{$x}</record> }
  </second>
  <third>
    { for $x in $t_thirdRecords  return <record>{$x}</record> }
  </third>
  <fourth>
    { for $x in $t_fourthRecords return <record>{$x}</record> }
  </fourth>
</service-results>
